class OrderCache:
    def get(self, order_id):
        val = client.get(f'order:{order_id}')
        return json.loads(val) if val else None

    def set(self, order_id, data):
        watermark_key = f'order:{order_id}:updated_at'
        incoming_ts = data.get('updated_at')
        existing_ts = client.get(watermark_key)
        if existing_ts and incoming_ts and incoming_ts <= existing_ts.decode():
            return  # stale write rejected: a fresher value is already known
        client.set(f'order:{order_id}', json.dumps(data))
        if incoming_ts:
            client.set(watermark_key, incoming_ts)

    def invalidate(self, order_id, updated_at=None):
        client.delete(f'order:{order_id}')
        if updated_at:
            client.set(f'order:{order_id}:updated_at', updated_at)
